describe('Username Availability Async Validation', () => {
  beforeEach(() => {
    cy.visit('/signup');
  });

  it('should successfully validate and submit form with available username', () => {
    cy.get('[data-testid="username-input"]').type('john_doe');
    cy.get('[data-testid="password-input"]').type('SecurePassword123');
    cy.get('[data-testid="submit-button"]').click();

    cy.intercept('POST', '/api/validate-username').as('validateUsername');
    cy.wait('@validateUsername').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
      expect(interception.response.body.available).to.equal(true);
    });

    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Username is available');
    cy.get('[data-testid="form-container"]').should('not.exist');
  });

  it('should display error when username is already taken', () => {
    cy.get('[data-testid="username-input"]').type('jane_doe');
    cy.get('[data-testid="password-input"]').type('SecurePassword123');
    cy.get('[data-testid="submit-button"]').click();

    cy.intercept('POST', '/api/validate-username').as('validateUsername');
    cy.wait('@validateUsername').then((interception) => {
      expect(interception.response.statusCode).to.equal(409);
      expect(interception.response.body.available).to.equal(false);
    });

    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Username is already taken');
    cy.get('[data-testid="form-container"]').should('be.visible');
    cy.get('[data-testid="submit-button"]').should('be.disabled');
  });
});
